async function executerEnPool(taches, concurrence) {
  const resultats = new Array(taches.length);
  let index = 0;

  async function worker() {
    while (index < taches.length) {
      const currentIdx = index++;
      try {
        resultats[currentIdx] = await taches[currentIdx]();
      } catch (err) {
        resultats[currentIdx] = err;
      }
    }
  }

  const workers = Array.from({ length: Math.min(concurrence, taches.length) }, worker);
  await Promise.all(workers);
  return resultats;
}

function creerSubject() {
  const subscribers = [];
  let isCompleted = false;
  let isErrored = false;

  return {
    next(val) {
      if (!isCompleted && !isErrored) {
        subscribers.forEach(sub => sub.next && sub.next(val));
      }
    },
    error(err) {
      if (!isCompleted && !isErrored) {
        isErrored = true;
        subscribers.forEach(sub => sub.error && sub.error(err));
      }
    },
    complete() {
      if (!isCompleted && !isErrored) {
        isCompleted = true;
        subscribers.forEach(sub => sub.complete && sub.complete());
      }
    },
    subscribe(observer) {
      const sub = { ...observer };
      subscribers.push(sub);
      // Replay logic is not requested, but we ensure immediate execution for current state if needed
      return {
        unsubscribe: () => {
          const idx = subscribers.indexOf(sub);
          if (idx > -1) subscribers.splice(idx, 1);
        }
      };
    }
  };
}

function memoiserAsync(fn) {
  const cache = new Map();
  const pendingPromises = new Map();

  return async function(...args) {
    const key = JSON.stringify(args);
    if (cache.has(key)) return cache.get(key);
    if (pendingPromises.has(key)) return pendingPromises.get(key);

    const promise = fn(...args).then(result => {
      cache.set(key, result);
      pendingPromises.delete(key);
      return result;
    }).catch(err => {
      pendingPromises.delete(key);
      throw err;
    });

    pendingPromises.set(key, promise);
    return promise;
  };
}

async function chargerUtilisateur(id) {
  try {
    const response = await fetch('/api/user/' + id);
    const resultat = await response.json();
    return resultat;
  } catch (error) {
    throw error;
  }
}

function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let failures = 0;
  let state = 'CLOSED'; // CLOSED, OPEN, HALF_OPEN
  let lastFailureTime = null;

  return async function(...args) {
    if (state === 'OPEN') {
      if (Date.now() - lastFailureTime > delaiResetMs) {
        state = 'HALF_OPEN';
      } else {
        throw new Error('Circuit Breaker is OPEN');
      }
    }

    try {
      const result = await fn(...args);
      if (state === 'HALF_OPEN') {
        state = 'CLOSED';
        failures = 0;
      }
      return result;
    } catch (error) {
      failures++;
      lastFailureTime = Date.now();
      if (failures >= seuil) {
        state = 'OPEN';
      }
      throw error;
    }
  };
}
